var e=[{title:`Förbered innan du lastar stången`,text:`Kontrollera att bänken, racket, stången, låsen och golvet passar övningen. I ett knäböjsrack fångar säkerhetsstift eller remmar på rätt höjd stången om du inte kan resa dig med den. Om du tränar ensam, försök inte göra bänkpress nära maxvikt utan säkerhetsanordningar.`},{title:`Vad en spotter gör`,text:`Före en bänkpress med skivstång, kom överens med din spotter om du vill ha hjälp att lyfta ur stången, när de ska börja hjälpa till och vilka kommandon ni ska använda. En spotter måste kunna hjälpa till och får inte distrahera dig. En oerfaren spotter kan inte garantera din säkerhet under en mycket tung vikt.`},{title:`Att släppa vikten beror på utrustningen`,text:`Plattformar för tyngdlyftning och bumperskivor är gjorda för vissa kontrollerade släpp. Hemmagolv, trånga gym och justerbara hantlar kanske inte är det. Öva aldrig improviserade nödsläpp nära människor eller ömtålig utrustning. Innan du försöker dig på hårda lyft, lär dig undanmanövern för din utrustning av en kvalificerad instruktör.`},{title:`Minska behovet av undsättning`,text:`Lämna repetitioner i reserv, välj en vikt du kan kontrollera och använd en maskin- eller hantelvariant när den passar din uppställning bättre. Du behöver inte träna till muskulär utmattning för att göra framsteg, särskilt vid komplexa lyft.`},{title:`Så använder du TrainUp`,text:`TrainUp förutsätter inte att du har en spotter, ett rack eller en säker plats att släppa vikter. Programmet väljer bara övningar som passar den utrustning och det utrymme du anger i Profil, så håll de inställningarna korrekta. Det föreskriver inte heller vikter: du väljer belastningen.`}];var r=[{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM 2026: praktisk vägledning`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var a={sections:e,sources:r};export{a as default,e as sections,r as sources};